from tests_src import T, Q2, TF

T(18, "18-7", "Beatrix Potter and Peter Rabbit", "Information Report", [
"Beatrix Potter was born in London in 1866. She loved animals, and she loved to draw. When she was a girl, she kept many small pets in her schoolroom. She had mice, newts, birds and rabbits. She drew and painted them again and again.",
"One of her rabbits was called Peter Piper. Beatrix liked to watch him and draw him. He gave her an idea for a story about a naughty little rabbit.",
"In 1893, Beatrix wrote a picture letter to a boy called Noel. The letter told the story of four young rabbits. One of them was called Peter. Beatrix drew pictures in the letter to go with her words.",
"Later, Beatrix wanted to turn her story into a book. Six publishers said no. So in 1901 she had 250 copies printed herself and gave them to her friends and family. The next year, a company called Frederick Warne made the book for shops to sell. It was called The Tale of Peter Rabbit, and it was a big success.",
"Beatrix wrote many more books about animals. In 1905, she used the money from her books to buy a farm called Hill Top. It is in the Lake District, in the north of England. She drew the farm and the countryside for her stories.",
"Beatrix loved the countryside and wanted it to stay beautiful. She left about 4,000 acres of land, and many farms, to the National Trust. This is a charity that looks after special places. Today, people can visit these places and enjoy them.",
], [
 dict(d="2b",k="mc",m=1,q="Where was Beatrix Potter born?",opts=["Wales","Kent","London","The Lake District"],a="C"),
 dict(d="2b",k="find",m=1,q="Find and copy the name of one of Beatrix’s pet rabbits.",a="Peter Piper",g="Accept “Peter Piper” only. Do not accept “Peter” alone or “Peter Rabbit”."),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, the book was “a big success”. What does this mean?",opts=["It cost a lot of money","It went very well","It was hard to read","It was a long book"],a="B"),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Beatrix bought Hill Top.","Beatrix wrote a picture letter to Noel.","A company called Frederick Warne made the book.","Beatrix had 250 copies printed for her friends and family."],a=[4,1,3,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Beatrix drew pictures in her letter to Noel.","Peter Piper was a mouse.","Hill Top is a farm.","Beatrix wrote only one book."],a=["T","F","T","F"],g=TF),
 dict(d="2b",k="short",m=1,q="Why did Beatrix have 250 copies of her story printed herself?",a="Six publishers had said no.",g="Accept: publishers said no / no publisher wanted it / she wanted to give the book to friends and family."),
 dict(d="2d",k="short",m=1,q="How can you tell that Beatrix liked animals? Give one clue from the text.",a="Any one of: she kept many pets; she drew and painted them; she wrote books about animals.",g="Accept any one clear clue from the text."),
 dict(d="2d",k="short",m=1,q="Beatrix bought Hill Top with money from her books. What does this tell you about her books?",a="Lots of people bought them / they sold well.",g="Accept any answer that shows the books were popular or made a lot of money."),
 dict(d="2d",k="short",m=1,q="How did Beatrix’s love of the countryside help other people?",a="People can visit the places she left and enjoy them.",g="Accept: people can visit the land / the special places are looked after for everyone."),
 dict(d="2c",k="mc",m=1,q="What is this text mostly about?",opts=["How to look after pet rabbits at home","How to print and sell a book at home","The history of the city of London","The life and books of Beatrix Potter"],a="D"),
])

T(19, "19-7", "Running for Gold in Athens", "Recount (Historical)", [
"Kelly Holmes was born on the 19th of April 1970 in a village called Pembury, in Kent. When she was 18 years old, she joined the army. In the army, Kelly played many sports, and she became the army judo champion. Later, she chose to concentrate on running.",
"Kelly trained very hard. She ran in races in many places, and she worked with her coaches to become faster and stronger.",
"In 2004, the Olympic Games were held in Athens, in Greece. Kelly was 34 years old, and she went there to run in two races. The first was the 800 metres, which is twice around a running track.",
"On the 23rd of August 2004, Kelly ran in the 800 metres final. Near the end of the race, she moved into the lead. She held off the other runners and crossed the line first. Her time was less than two minutes. Kelly had won an Olympic gold medal.",
"Five days later, on the 28th of August 2004, Kelly ran in the 1500 metres final. This is a longer race. It is nearly four times around the track. Once again, Kelly sped up near the end and finished in front of all the others. She had won a second gold medal.",
"Only two women before Kelly had ever won both of these races at the same Olympic Games. Now she had joined them.",
"After the Games, Kelly was made a Dame. This is a special title that is given to women who have done something very important. Kelly’s two gold medals showed what can happen when a person keeps on trying.",
], [
 dict(d="2b",k="mc",m=1,q="In which country were the 2004 Olympic Games held?",opts=["Greece","Kent","Wales","France"],a="A"),
 dict(d="2b",k="short",m=1,q="How old was Kelly when she joined the army?",a="18 (years old).",g="Accept 18 or eighteen."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does “concentrate on” mean?",opts=["Stop doing it for a long time","Feel scared or worried about","Give most of her time to","Talk to other people about"],a="C"),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Kelly was born in Greece.","Kelly became the army judo champion.","Kelly won two gold medals in 2004.","The 1500 metres final came first."],a=["F","T","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Kelly won the 1500 metres.","Kelly joined the army.","Kelly was made a Dame.","Kelly won the 800 metres."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="find",m=1,q="Find and copy the date of the 800 metres final.",a="23rd of August 2004",g="Accept “the 23rd of August 2004”. The full date must be copied."),
 dict(d="2d",k="short",m=1,q="How can you tell that Kelly was good at sports other than running?",a="She became the army judo champion.",g="Accept: she was the army judo champion / she played many sports and won at judo."),
 dict(d="2d",k="short",m=1,q="Why was it special to win both races at the same Games?",a="Only two women had done it before / it is very hard to do.",g="Accept: hardly anyone had done it / it was rare / very few women had done it."),
 dict(d="2d",k="short",m=1,q="Why do you think Kelly was made a Dame?",a="Because she had won two gold medals / done something very important.",g="Accept any answer linked to her Olympic wins or her great success."),
 dict(d="2c",k="mc",m=1,q="Which sentence tells you best what this text is about?",opts=["Kelly Holmes trained in the army and then gave up running.","Kelly Holmes won two gold medals at the Olympic Games.","Kelly Holmes ran in one race and came in second place.","Kelly Holmes wrote a book about her life in Kent."],a="B"),
])

T(20, "20-7", "Stevie Wonder, Musician", "Information Report", [
"Stevie Wonder is a very famous musician. He was born on the 13th of May 1950 in Saginaw. This is a city in Michigan, in the United States. Stevie has been blind since he was a baby. He grew up in a city called Detroit.",
"Music filled Stevie’s life from a very young age. He learned to play the piano, the harmonica and the drums. By the time he was eight years old, he was already a skilled musician. He sang beautifully too.",
"While he was still a boy, Stevie joined a record company called Motown. The company gave him a new name: Little Stevie Wonder.",
"In 1963, when Stevie was 13 years old, he made a record called “Fingertips”. It was recorded in front of a live audience. It became number one in the American charts. No singer had ever been so young to have a number-one hit there.",
"In the 1970s, Stevie made a series of famous albums. They included Talking Book in 1972, Innervisions in 1973 and Songs in the Key of Life in 1976. Many people bought these albums. Lots of the songs are still played today.",
"Stevie has won 25 Grammy Awards. These are important prizes in the world of music. They are given out every year to musicians from many countries. He has also won an Academy Award for a song called “I Just Called to Say I Love You”. In 2014, he was given the Presidential Medal of Freedom. This is one of the highest honours in the country.",
"Today, Stevie Wonder’s songs are loved by people of all ages. His music shows how one person can bring joy to people all around the world.",
], [
 dict(d="2b",k="mc",m=1,q="In which city was Stevie born?",opts=["Detroit","Saginaw","Nashville","Chicago"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the name of the record company that Stevie joined.",a="Motown",g="Accept “Motown” only."),
 dict(d="2b",k="short",m=1,q="How old was Stevie when he made “Fingertips”?",a="13 (years old).",g="Accept 13 or thirteen."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does “a series of famous albums” mean?",opts=["A single album made by many singers","A short break between two albums","Some albums, one after another","A prize given to the best album"],a="C"),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Stevie made the album Talking Book.","Stevie was given the Presidential Medal of Freedom.","Stevie joined Motown.","Stevie’s record “Fingertips” became number one."],a=[3,4,1,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Stevie learned to play the harmonica.","Stevie was born in Detroit.","Stevie won an Academy Award for “Fingertips”.","Stevie has won an Academy Award."],a=["T","F","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="Why do you think Motown called him “Little Stevie Wonder”?",a="Because he was young (a boy) and wonderful at music.",g="Accept any answer that links “little” to his young age and/or “wonder” to his amazing talent."),
 dict(d="2d",k="short",m=1,q="How can you tell that “Fingertips” was a very popular record?",a="It became number one in the American charts.",g="Accept: it reached number one / lots of people bought it."),
 dict(d="2d",k="short",m=1,q="The Presidential Medal of Freedom is “one of the highest honours in the country”. What does this tell you about how people felt about Stevie?",a="They respected and admired him and thought his music was very important.",g="Accept: they thought he was very special / they admired his work / they were proud of him."),
 dict(d="2g",k="short",m=1,q="The writer says, “Music filled Stevie’s life”. What does this tell you?",a="Music was very important to him / he had music all around him all the time.",g="Accept any answer that shows music was a big or important part of his life."),
 dict(d="2c",k="mc",m=1,q="Which is the best heading for paragraph 6?",opts=["Stevie’s first pets","Stevie’s home in Detroit","The story of a number-one record","Stevie’s prizes and honours"],a="D"),
])
